const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southLA = ee.Geometry.Polygon(
    [
      [-118.35, 33.90],
      [-118.35, 34.05],
      [-118.05, 34.05],
      [-118.05, 33.90],
      [-118.35, 33.90]
    ]
  );

  const startDay = '10-01';
  const endDay = '10-23';

  // 2. Data Acquisition & Check
  const getNo2Data = (year, geometry) => {
    const startDate = `${year}-${startDay}`;
    const endDate = `${year}-${endDay}`;

    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select('NO2_tropospheric_column')
      .filterMetadata('qa_value', '>', 0.75); // Filter for good quality data

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { collection: null, size: 0, meanValue: null, pixelCount: 0 };
    }

    const meanImage = collection.mean().clip(geometry);

    const scale = 3000; // Appropriate scale for Sentinel-5P NO2 data
    const pixelCount = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NO2_tropospheric_column').getInfo();

    let meanValue = null;
    if (pixelCount > 0) {
      meanValue = meanImage.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NO2_tropospheric_column').getInfo();
    }

    return { collection: collection, size: collectionSize, meanValue: meanValue, pixelCount: pixelCount };
  };

  const data2021 = getNo2Data(2021, southLA);
  const data2019 = getNo2Data(2019, southLA);
  const data2018 = getNo2Data(2018, southLA);

  if (data2021.size === 0 || data2019.size === 0 || data2018.size === 0) {
    console.log(`2021 Images: ${data2021.size}`);
    console.log(`2019 Images: ${data2019.size}`);
    console.log(`2018 Images: ${data2018.size}`);
    console.log("C1");
    return;
  }

  console.log(`2021 Images: ${data2021.size}`);
  console.log(`2019 Images: ${data2019.size}`);
  console.log(`2018 Images: ${data2018.size}`);

  if (data2021.pixelCount === 0 || data2019.pixelCount === 0 || data2018.pixelCount === 0) {
    console.log(`2021 Valid Pixels: ${data2021.pixelCount}`);
    console.log(`2019 Valid Pixels: ${data2019.pixelCount}`);
    console.log(`2018 Valid Pixels: ${data2018.pixelCount}`);
    console.log("C2");
    return;
  }

  // 4. Calculation
  const no2_2021 = data2021.meanValue;
  const no2_2019 = data2019.meanValue;
  const no2_2018 = data2018.meanValue;

  if (no2_2021 === null || isNaN(no2_2021) ||
      no2_2019 === null || isNaN(no2_2019) ||
      no2_2018 === null || isNaN(no2_2018)) {
    console.log(`2021 NO2: ${no2_2021}`);
    console.log(`2019 NO2: ${no2_2019}`);
    console.log(`2018 NO2: ${no2_2018}`);
    console.log("C3");
    return;
  }

  const average_2018_2019 = (no2_2019 + no2_2018) / 2;

  // 5. Validation & Final Answer
  console.log(`2021 Mean NO2: ${no2_2021.toExponential(3)}`);
  console.log(`2019 Mean NO2: ${no2_2019.toExponential(3)}`);
  console.log(`2018 Mean NO2: ${no2_2018.toExponential(3)}`);
  console.log(`2018/2019 Average NO2: ${average_2018_2019.toExponential(3)}`);

  if (no2_2021 < average_2018_2019) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
